const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const dallasport = ee.Geometry.Point([-121.178, 45.609]).buffer(10000);
    const medford = ee.Geometry.Point([-122.875, 42.326]).buffer(10000);
    const start = ee.Date('2010-01-01');
    const end = ee.Date('2025-01-01');
    const band = 'maximum_2m_air_temperature';
    const thresholdK = ee.Number(105).subtract(32).multiply(5).divide(9).add(273.15); // 105F in Kelvin

    // 2. Data Acquisition & Check with fallback
    let col = ee.ImageCollection('ECMWF/ERA5_LAND/DAILY_AGGR')
      .filterDate(start, end)
      .select(band);
    let size = await col.size().getInfo();
    let datasetUsed = 'ECMWF/ERA5_LAND/DAILY_AGGR';
    if (size === 0) {
      const fallback = ee.ImageCollection('ECMWF/ERA5/DAILY')
        .filterDate(start, end)
        .select(band);
      const sizeFallback = await fallback.size().getInfo();
      if (sizeFallback === 0) {
        console.log(`Images: 0 in both ERA5-LAND and ERA5 for ${start.format('YYYY-MM-dd').getInfo()} to ${end.format('YYYY-MM-dd').getInfo()}`);
        console.log('C1');
        return;
      }
      col = fallback;
      size = sizeFallback;
      datasetUsed = 'ECMWF/ERA5/DAILY';
    }

    function kToF(k) {
      if (k === null || k === undefined) return null;
      return (k - 273.15) * 9 / 5 + 32;
    }

    async function analyzeRegion(name, geom) {
      const firstImg = ee.Image(col.first());
      const pixCount = await ee.Number(
        firstImg.reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: geom,
          scale: 9000,
          maxPixels: 1e9
        }).get(band)
      ).getInfo();

      if (pixCount === null || pixCount === 0) {
        return { name, status: 'C2' };
      }

      const colWithStats = col.map(function (img) {
        const stats = img.reduceRegion({
          reducer: ee.Reducer.mean().combine({ reducer2: ee.Reducer.max(), sharedInputs: true }),
          geometry: geom,
          scale: 9000,
          maxPixels: 1e9
        });
        return img.set({
          meanK: stats.get(`${band}_mean`),
          maxK: stats.get(`${band}_max`)
        });
      });

      const daysAbove = await colWithStats.filter(ee.Filter.gt('maxK', thresholdK)).size().getInfo();
      const maxOfMaxK = await ee.Number(colWithStats.aggregate_max('maxK')).getInfo();
      const maxOfMeanK = await ee.Number(colWithStats.aggregate_max('meanK')).getInfo();

      if (maxOfMaxK === null || isNaN(maxOfMaxK) || maxOfMeanK === null || isNaN(maxOfMeanK)) {
        return { name, status: 'C3' };
      }

      return {
        name,
        status: 'OK',
        pixCount,
        daysAbove,
        maxOfMaxF: kToF(maxOfMaxK),
        maxOfMeanF: kToF(maxOfMeanK),
        anyOver: daysAbove > 0
      };
    }

    console.log(`Dataset: ${datasetUsed}, Period: ${start.format('YYYY-MM-dd').getInfo()} to ${end.format('YYYY-MM-dd').getInfo()}, Images: ${size}`);
    console.log(`Threshold: 105°F = ${thresholdK.getInfo().toFixed(2)} K`);

    const resDallas = await analyzeRegion('Dallasport, WA', dallasport);
    const resMedford = await analyzeRegion('Medford, OR', medford);

    if (resDallas.status !== 'OK') {
      console.log(`Dallasport status: ${resDallas.status}`);
      console.log(resDallas.status);
      return;
    }
    if (resMedford.status !== 'OK') {
      console.log(`Medford status: ${resMedford.status}`);
      console.log(resMedford.status);
      return;
    }

    console.log(`Dallasport: Pixels=${resDallas.pixCount}, MaxF_mean=${resDallas.maxOfMeanF.toFixed(1)}, MaxF_px=${resDallas.maxOfMaxF.toFixed(1)}`);
    console.log(`Dallasport Days>105F (max px)=${resDallas.daysAbove}`);
    console.log(`Medford: Pixels=${resMedford.pixCount}, MaxF_mean=${resMedford.maxOfMeanF.toFixed(1)}, MaxF_px=${resMedford.maxOfMaxF.toFixed(1)}`);
    console.log(`Medford Days>105F (max px)=${resMedford.daysAbove}`);

    const finalYes = resDallas.anyOver && resMedford.anyOver;
    console.log(finalYes ? 'A' : 'B');
  } catch (err) {
    console.log(`Error: ${String(err).slice(0, 200)}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
